    std::string Utils::getAttributeName(const HlaObjectInstanceBase::ObjectClassType& objectType, const int& attribute) {
        auto classIt = objectClassTypeAttributesReverseMap.find(objectType);
        if (classIt != objectClassTypeAttributesReverseMap.end()) {
            auto attrIt = classIt->second.find(attribute);
            if (attrIt != classIt->second.end()) {
                return attrIt->second;
            }
        }
        return {}; // Retorna string vacío si no se encuentra
    }
    int Utils::getAttributeFromName(const HlaObjectInstanceBase::ObjectClassType& objectType, const std::string& attributeName) {
        auto classIt = objectClassTypeAttributesMap.find(objectType);
        if (classIt != objectClassTypeAttributesMap.end()) {
            auto attrIt = classIt->second.find(attributeName);
            if (attrIt != classIt->second.end()) {
                return attrIt->second;
            }
        }
        return -1; // Retorna -1 si no se encuentra
    }

    HlaObjectInstanceBase::ObjectClassType Utils::ObjectClassTypeFromSiso(unsigned char kind, unsigned char domain, bool isTanker) {
        switch (kind)
        {
        case enumsCommon_Client::EntityKind::Platform:
        {
            switch (domain)
            {
            case enumsCommon_Client::EntityDomain::Air: {
                /*if (isTanker)
                    return HlaObjectInstanceBase::ObjectClassType::TANKER_AIRCRAFT;
                else*/
                    return HlaObjectInstanceBase::ObjectClassType::AIRCRAFT;
            }
            case enumsCommon_Client::EntityDomain::Land: return HlaObjectInstanceBase::ObjectClassType::GROUND_VEHICLE;
            case enumsCommon_Client::EntityDomain::Surface: return HlaObjectInstanceBase::ObjectClassType::SURFACE_VESSEL;
            case enumsCommon_Client::EntityDomain::Subsurface: return HlaObjectInstanceBase::ObjectClassType::SUBMERSIBLE_VESSEL;
            case enumsCommon_Client::EntityDomain::Space: return HlaObjectInstanceBase::ObjectClassType::SPACECRAFT;
            }
            return HlaObjectInstanceBase::ObjectClassType::HLAOBJECT_ROOT;
        }
        case enumsCommon_Client::EntityKind::Munition: return HlaObjectInstanceBase::ObjectClassType::MUNITION;
        case enumsCommon_Client::EntityKind::LifeForm: return HlaObjectInstanceBase::ObjectClassType::LIFEFORM;
        case enumsCommon_Client::EntityKind::Supply: return HlaObjectInstanceBase::ObjectClassType::SUPPLIES;
        case enumsCommon_Client::EntityKind::SensorEmitter: return HlaObjectInstanceBase::ObjectClassType::SENSOR;
        }
        return HlaObjectInstanceBase::ObjectClassType::HLAOBJECT_ROOT;
    }

