    std::vector<unsigned long long> Utils::ConverteVectorCharToVectorLong(std::vector<char> charVector)
    {
        std::vector<unsigned long long> ret;
        ret.reserve(charVector.size() / sizeof(unsigned long long));
        for (size_t i = 0; i < charVector.size(); i += sizeof(unsigned long long))
        {
            unsigned long long value = 0;
            for (size_t j = 0; j < sizeof(unsigned long long) && (i + j) < charVector.size(); ++j)
            {
                value |= static_cast<unsigned long long>(charVector[i + j]) << (j * 8);
            }
            ret.push_back(value);
        }
        return ret;
    }
    std::vector<char> Utils::ConvertVectorLongToVectorChar(std::vector<unsigned long long>& longVector)
    {
        std::vector<char> charVector;
        charVector.reserve(longVector.size() * sizeof(unsigned long long));
        for (auto& value : longVector)
        {
            char* data = reinterpret_cast<char*>(&value);
            charVector.insert(charVector.end(), data, data + sizeof(unsigned long long));
        }
        return charVector;
    }
